<x-layouts.workspace title="Testimonies" :ministry-name="$settings->name" :user-name="$user->name" user-role="Publishing workspace"><header class="workspace-page-heading"><p>EDITORIAL WORKFLOW</p><h1>Testimonies</h1><span>Capture stories, review member submissions, confirm consent, and publish with care.</span></header>@if(session('status'))<div class="notice success" role="status">{{ session('status') }}</div>@endif @if($errors->any())<div class="notice error" role="alert">{{ $errors->first() }}</div>@endif<nav class="testimony-admin-tabs" aria-label="Testimony filters"><a href="{{ route('staff.testimonies') }}" @class(['active'=>$activeStatus===''])>All</a>@foreach(['submitted','draft','published','rejected','archived'] as $status)<a href="{{ route('staff.testimonies',['status'=>$status]) }}" @class(['active'=>$activeStatus===$status])>{{ str($status)->headline() }}</a>@endforeach</nav><div class="testimony-admin-grid"><section class="data-panel testimony-editor"><header><div><p>STAFF ENTRY</p><h2>Add a testimony</h2></div></header><form method="post" action="{{ route('staff.testimonies.store') }}">@csrf<div class="editor-grid"><label>Title<input name="title" maxlength="180" required></label><label>Author name<input name="author_name" maxlength="160" required></label><label>Category<select name="category">@foreach($categories as $category)<option value="{{ $category }}">{{ str($category)->headline() }}</option>@endforeach</select></label></div><label>Full testimony<textarea name="body" rows="9" minlength="20" maxlength="12000" required></textarea></label><div class="editor-checks"><label><input type="checkbox" name="consent_public" value="1"> Public sharing consent recorded</label><label><input type="checkbox" name="show_author_name" value="1" checked> Show author name</label><label><input type="checkbox" name="featured" value="1"> Feature this story</label></div><button type="submit">Save draft</button></form></section><section class="data-panel testimony-queue"><header><div><p>REVIEW QUEUE</p><h2>{{ $testimonies->total() }} stories</h2></div></header><div class="queue-list">@forelse($testimonies as $item)<article><div class="queue-top"><span class="queue-status status-{{ $item->status }}">{{ str($item->status)->headline() }}</span><small>{{ str($item->category)->headline() }}</small></div><div class="testimony-review-author">@if($item->profile_image_url)<img src="{{ $item->profile_image_url }}" alt="">@else<span>{{ str($item->author_name)->substr(0,1)->upper() }}</span>@endif<strong>{{ $item->author_name }}</strong></div><h3>{{ $item->title }}</h3><p>{{ str($item->body)->limit(170) }}</p><footer><span>{{ $item->show_author_name ? $item->author_name : 'Anonymous' }}</span><time>{{ str($item->created_at)->substr(0,10) }}</time></footer><details><summary>Edit and review</summary><form method="post" action="{{ route('staff.testimonies.update',$item->id) }}">@csrf @method('PUT')<input name="title" value="{{ $item->title }}" required><input name="author_name" value="{{ $item->author_name }}" required><select name="category">@foreach($categories as $category)<option value="{{ $category }}" @selected($item->category===$category)>{{ str($category)->headline() }}</option>@endforeach</select><textarea name="body" rows="8" required>{{ $item->body }}</textarea><label><input type="checkbox" name="consent_public" value="1" @checked($item->consent_public)> Public consent recorded</label><label><input type="checkbox" name="show_author_name" value="1" @checked($item->show_author_name)> Show author</label><label><input type="checkbox" name="featured" value="1" @checked($item->featured)> Featured</label><button type="submit">Save changes</button></form><form class="review-actions" method="post" action="{{ route('staff.testimonies.review',$item->id) }}">@csrf @method('PATCH')<textarea name="review_notes" rows="2" placeholder="Internal review note">{{ $item->review_notes }}</textarea><button name="action" value="publish">Publish</button><button name="action" value="reject">Reject</button><button name="action" value="archive">Archive</button></form></details></article>@empty<div class="queue-empty">No testimonies match this view.</div>@endforelse</div><div class="pagination-wrap">{{ $testimonies->links() }}</div></section></div><style>.testimony-review-author{display:flex;align-items:center;gap:8px;color:var(--ink);font-size:.7rem}.testimony-review-author img,.testimony-review-author>span{display:grid;width:30px;height:30px;place-items:center;border-radius:50%;object-fit:cover;background:color-mix(in srgb,var(--action) 13%,var(--surface));color:var(--action);font-weight:850}.testimony-admin-tabs{display:flex;gap:8px;overflow:auto;margin:0 0 22px;padding:4px 2px 8px}.testimony-admin-tabs a{white-space:nowrap;border:1px solid var(--line-strong);border-radius:999px;padding:9px 14px;background:var(--surface);color:var(--muted);font-size:.68rem;font-weight:800;text-decoration:none}.testimony-admin-tabs a.active{border-color:var(--brand);background:color-mix(in srgb,var(--brand) 12%,var(--surface));color:var(--brand)}.testimony-admin-grid{display:grid;grid-template-columns:minmax(320px,.82fr) minmax(0,1.18fr);gap:20px}.testimony-editor,.testimony-queue{display:grid;gap:18px;min-width:0;overflow:hidden;border:1px solid var(--line);border-radius:18px;background:var(--surface);box-shadow:var(--shadow-sm)}.testimony-editor>header,.testimony-queue>header{padding:20px 22px;border-bottom:1px solid var(--line);background:var(--surface-muted)}.testimony-editor header p,.testimony-queue header p{margin:0 0 6px;color:var(--brand);font-size:.58rem;font-weight:850;letter-spacing:.14em}.testimony-editor header h2,.testimony-queue header h2{margin:0;color:var(--ink);font-size:1.08rem}.testimony-editor form{display:grid;gap:15px;padding:0 22px 22px}.testimony-editor label,.editor-grid label,.queue-list details form{display:grid;gap:7px;color:var(--ink);font-size:.68rem;font-weight:760}.editor-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.testimony-editor input,.testimony-editor select,.testimony-editor textarea,.queue-list input,.queue-list select,.queue-list textarea{box-sizing:border-box;width:100%;border:1px solid var(--line-strong);border-radius:10px;padding:10px 11px;background:var(--surface);color:var(--ink);font:inherit}.editor-checks{display:grid;gap:9px;padding:13px;border:1px solid var(--line);border-radius:12px;background:var(--surface-muted)}.editor-checks label,.queue-list label{display:flex;align-items:flex-start;gap:9px;color:var(--muted);font-size:.67rem}.editor-checks input,.queue-list label input{width:auto}.queue-list{display:grid;gap:13px;padding:0 18px 4px}.queue-list article{display:grid;gap:11px;padding:17px;border:1px solid var(--line);border-radius:14px;background:var(--surface-muted)}.queue-list h3,.queue-list p{margin:0}.queue-list p{color:var(--muted);font-size:.7rem;line-height:1.6}.queue-list footer,.queue-top{display:flex;justify-content:space-between;gap:10px;color:var(--muted);font-size:.62rem}.queue-status{border-radius:999px;padding:5px 9px;background:color-mix(in srgb,var(--action) 11%,var(--surface));color:var(--action);font-size:.59rem;font-weight:850;text-transform:uppercase}.queue-list details{border-top:1px solid var(--line);padding-top:12px}.queue-list summary{cursor:pointer;color:var(--brand);font-size:.68rem;font-weight:820}.queue-list details form{margin-top:13px}.review-actions{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px!important}.review-actions textarea{grid-column:1/-1}.notice{margin-bottom:16px;border:1px solid var(--line);border-radius:11px;padding:12px 14px;font-size:.72rem}.notice.success{color:var(--success)}.notice.error{color:var(--danger)}@media(max-width:900px){.testimony-admin-grid{grid-template-columns:1fr}}@media(max-width:600px){.editor-grid{grid-template-columns:1fr}.review-actions{grid-template-columns:1fr!important}.queue-top,.queue-list footer{align-items:flex-start;flex-direction:column}}</style></x-layouts.workspace>
